INSERT INTO `aboutinfo` (`id`, `spiritText`, `missionText`, `visionText`, `philosophyTitle`, `philosophyPillars`, `updatedAt`) VALUES
(1, 'Success is born through honesty, persistence, and commitment in the light of constant prayer.', 'We are a transformation-making company that creates value to society based on interdependence co-arising.', 'To become one of the most respected palm oil and renewable energy companies, in terms of operational excellence and commitment to live in harmony with mother nature.', 'Our Philosophy', '[{\"id\":\"human\",\"title\":\"Human Values\",\"text\":\"To understand and apply humanitarian values encompassing: Truth, Right Conduct, Love, Non-Violence, and Peace.\\nNot violating religious prohibitions.\\nSincerity and harmony in thinking, speaking and taking action.\\n\"},{\"id\":\"ethics\",\"title\":\"Business Ethics\",\"text\":\"Using the ethical norms prevailing in the community in interaction and management of business environment so that there will finally be \\\"a sustainable mutual benefit\\\".\\nAlso paying attention to various problems emerging in DAW\'s business mission although formally this is not their responsibility.\"},{\"id\":\"unity\",\"title\":\"Unity Through Harmony\",\"text\":\"To maintain harmony and unity with the business community internally (employees and shareholders).\\nTo maintain equilibrium and harmony between the business aspect and other aspects.\\n\"},{\"id\":\"speed\",\"title\":\"Speed and Leading Change\",\"text\":\"To maintain and raise the speed in the way of thinking and way of action.\\nTo institutionalize changes properly and sustain ably so that there will be an added value for the company with technological power as its pillar.\"},{\"id\":\"smart\",\"title\":\"Working Smart in Learning Culture\",\"text\":\"Diligent, persevering, serious and consistent in the work one is involved in.\\nEmphasising the process of swift, systematic and accurate working.\\nInvariably enhancing the method and quality of working through self-development in a culture of learning continuously nurtured by and along with the company.\"}]', '2026-03-17 01:03:08');

