INSERT INTO `businesssections` (`id`, `category`, `title`, `htmlContent`, `hasMap`, `createdAt`, `updatedAt`) VALUES
('energy', 'Energy', 'Energy Focus.', '<p><span style=\"color: oklch(0.208 0.042 265.755);\">DAW&nbsp;Group&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Energy&nbsp;Division</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;focuses&nbsp;within&nbsp;the&nbsp;renewable&nbsp;energy&nbsp;sector.&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">In&nbsp;2014</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;we&nbsp;obtained&nbsp;one&nbsp;hydropower&nbsp;project&nbsp;in&nbsp;North&nbsp;Sumatera&nbsp;(Toba&nbsp;Samosir&nbsp;Region),&nbsp;with&nbsp;a&nbsp;capacity&nbsp;of&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">15&nbsp;Megawatts</strong><span style=\"color: oklch(0.208 0.042 265.755);\">.&nbsp;We&nbsp;believe&nbsp;hydropower&nbsp;in&nbsp;Indonesia&nbsp;is&nbsp;really&nbsp;important&nbsp;in&nbsp;contributing&nbsp;to&nbsp;the&nbsp;country’s&nbsp;heavy&nbsp;need&nbsp;of&nbsp;power&nbsp;generation.</span></p><p><strong style=\"color: oklch(0.208 0.042 265.755);\">In&nbsp;2011,</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;we&nbsp;entered&nbsp;into&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Operation&nbsp;and&nbsp;Maintenance&nbsp;services</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;for&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Indonesia&nbsp;state&nbsp;owned</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">electricity&nbsp;company&nbsp;(PLN)</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;focusing&nbsp;mainly&nbsp;in&nbsp;the&nbsp;coal&nbsp;fired&nbsp;power&nbsp;plants.&nbsp;Currently,&nbsp;we&nbsp;are&nbsp;serving&nbsp;five&nbsp;PLN&nbsp;power&nbsp;plants&nbsp;ranging&nbsp;from&nbsp;Sumatera,&nbsp;Kalimantan,&nbsp;and&nbsp;Sulawesi.</span></p><blockquote><span style=\"color: oklch(0.208 0.042 265.755);\">We&nbsp;provide&nbsp;solutions&nbsp;to&nbsp;clients&nbsp;in&nbsp;various&nbsp;industries&nbsp;such&nbsp;as:&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">food&nbsp;and&nbsp;beverage</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">textile</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">chemical</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;and&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">steel</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;to&nbsp;get&nbsp;maximum&nbsp;energy&nbsp;efficiency.</span></blockquote>', 1, '2026-03-13 10:38:23', '2026-03-13 04:44:46'),
('resources', 'Resources', 'Resource Focus.', '<p><span style=\"color: oklch(0.208 0.042 265.755);\">DAW&nbsp;Group&nbsp;Resources&nbsp;division&nbsp;focuses&nbsp;is&nbsp;in&nbsp;the&nbsp;Palm&nbsp;Oil&nbsp;business.&nbsp;Our&nbsp;palm&nbsp;oil&nbsp;plantation&nbsp;is&nbsp;located&nbsp;in&nbsp;East&nbsp;Kalimantan&nbsp;with&nbsp;total&nbsp;plantable&nbsp;area&nbsp;of&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">10,000&nbsp;hectares</strong><span style=\"color: oklch(0.208 0.042 265.755);\">.&nbsp;In&nbsp;the&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">downstream&nbsp;sector</strong><span style=\"color: oklch(0.208 0.042 265.755);\">,&nbsp;DAW&nbsp;Group&nbsp;currently&nbsp;have&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">four&nbsp;CPO&nbsp;Mills</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;in&nbsp;operation.&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Two&nbsp;CPO&nbsp;Mills</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;that&nbsp;are&nbsp;directly&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">owned&nbsp;by&nbsp;DAW</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;are&nbsp;located&nbsp;in&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">East&nbsp;Kalimantan</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;and&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Jambi&nbsp;Province</strong><span style=\"color: oklch(0.208 0.042 265.755);\">;&nbsp;and&nbsp;two&nbsp;other&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">CPO&nbsp;Mills&nbsp;in&nbsp;Lampung&nbsp;</strong><span style=\"color: oklch(0.208 0.042 265.755);\">and&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Jambi&nbsp;Province</strong><span style=\"color: oklch(0.208 0.042 265.755);\">&nbsp;are&nbsp;owned&nbsp;through&nbsp;</span><strong style=\"color: oklch(0.208 0.042 265.755);\">Tudung&nbsp;Group</strong><span style=\"color: oklch(0.208 0.042 265.755);\">.</span></p><p><span style=\"color: oklch(0.208 0.042 265.755);\">Below&nbsp;are&nbsp;the&nbsp;locations&nbsp;of&nbsp;our&nbsp;operating&nbsp;Palm&nbsp;Oil&nbsp;Plantations&nbsp;and&nbsp;Palm&nbsp;Oil&nbsp;Mills.</span></p>', 1, '2026-03-13 10:38:23', '2026-03-13 06:09:16');

