--
-- Dumping data for table `managements`
--

INSERT INTO `managements` (`id`, `name`, `role`, `description`, `level`, `order`, `photoUrl`, `createdAt`, `updatedAt`) VALUES
(1, 'Sudhamek AWS', 'Chariman', 'Mr Sudhamek is the Chairman of PT. Dharma Agung Wijaya since 2009. He is also the Chairman of Garudafood Group since 2012. Previously, he had been the CEO of Garudafood group for 18 years.  \r\n\r\nIn 2016, Mr. Sudhamek was inducted as a member of the National Economic & Industry Committe by The President of the Republic of Indonesia: Mr. Joko Widodo; within the same year, He was also awarded with Doctor Honoris Causa by The Universitas Kristen Satya Wacana, on his concept called the Spirituality Based Company (SBC). He is affiliated with other organisations, including as the Chairman of the oldest Buddhist organization in Indonesia (Buddhayana), one of the founders of ICRP (Indonesian Conference on Religion And Peace), and as the Board of Governors of an educational institution called Global Sevilla School, which he established together with the late Mr. Nurcholish Madjid. \r\n', 'chairman', 1, '/uploads/1773279893375-969525494.png', '2026-03-12 01:44:53', '2026-03-12 01:44:53'),
(2, 'Adhitya Soenjoto', 'President Director', 'He is the President Director of PT. Dharma Agung Wijaya since 2009, responsible for managing the whole business operation of DAW Group. He sits in the management board of other business units under DAW Group, such as: the Director of PT. Hanusentra Agro Lestari (a palm oil plantation) since 2012, the Director of PT Sentosa Bumi Wijaya (a palm oil mill) since 2010 and the Director of PT. Bina Niaga Multiusaha (precision stainless steel rolling mill) since 2016. From 2007 until 2008, he worked at Ernst & Young in Hong Kong, as an auditor. He obtained his Bachelor of Art Degree in Economics in 2005, at The University of Michigan - Ann Arbor, USA. He then obtained his MBA Degree in 2009, at Babson College, Boston - Massachusetts, USA.', 'director', 1, NULL, '2026-03-12 09:28:17', '2026-03-12 09:28:17'),
(3, 'Yudie Soenjoto', 'Vice President Director', 'He is the Director of PT. Dharma Agung Wijaya since June 2014, with management responsibility over Energy Division of DAW group. Within the energy division, he serves as director at PT. BEA. He is affiliated with an educational institution a Board Member Executive Secreatry at Global Sevilla School. Prior to joining DAW group, he had served as Project Manager at Garudafood Group, from February 2010 until December 2011. He obtained his Bachelor Degree in Mechanical Engineering from University of Michigan - Ann Arbor. In 2014, he completed his M.B.A in entrepreneurship at Babson College, Wellesley, MA.', 'director', 2, '/uploads/photo-1773725805880-128737937.jpg', '2026-03-12 09:28:37', '2026-03-17 05:36:45'),
(4, 'Hendy Liusgria', 'Chief Financial Officer', 'He is the Chief Financial Officer for PT. Dharma Agung Wijaya since 2019, with management responsibilities over the financials and tax of both Resources Division and Energy Division of DAW Group. Mr. Hendy had extensive and long term experiences in finance and tax, previously served as the CFO of  PT Sinar Niaga Sejahtera, which is the distribution company serving Garudafood Group.', 'division', 1, NULL, '2026-03-12 09:29:00', '2026-03-12 09:29:00'),
(5, 'Eduard Siregar', 'Division Head', 'Previously, he served the responsibility as Head of Financial Accounting under the Resources Division. In 2017, Mr Eduard served as the Head of Resources division of DAW, managing the operation of four palm oil mills and plantation in Sumatera and Kalimantan.\r\n', 'division', 2, NULL, '2026-03-12 09:29:17', '2026-03-12 09:29:17'),
(6, 'Sentiyono', 'Division Head', 'He is the Head of Bioenergy Division of DAW Group since 2017, managing the operation of palm kernel shells trading business and renewable energy developments in the bioenergy sectors. He is also a certified Toyota Trainer in various subjects, such as Toyota Practical Problem Solving, Quality Control Check, and Project management.', 'division', 3, NULL, '2026-03-12 09:29:32', '2026-03-12 09:29:32');

