INSERT INTO `pages` (`id`, `title`, `slug`, `subtitle`, `heroImage`, `templateType`, `content`, `metaDescription`, `createdAt`, `updatedAt`, `sidebarLinks`, `showDropCap`) VALUES
('415457c1-1930-4830-9250-00d101327e0d', 'Sustainability Commitment', 'sustainability-commitment', '', 'data:image/jpeg;base64,', 'classic', '<h1><strong>Building&nbsp;a&nbsp;Greener&nbsp;Legacy</strong></h1><p></p><p>At&nbsp;DAW&nbsp;Group,&nbsp;sustainability&nbsp;is&nbsp;not&nbsp;a&nbsp;choice,&nbsp;but&nbsp;our&nbsp;foundation.&nbsp;We&nbsp;believe&nbsp;that&nbsp;every&nbsp;resource&nbsp;we&nbsp;manage&nbsp;should&nbsp;contribute&nbsp;to&nbsp;a&nbsp;balanced&nbsp;ecosystem.&nbsp;Our&nbsp;ESG&nbsp;(Environmental,&nbsp;Social,&nbsp;and&nbsp;Governance)&nbsp;framework&nbsp;ensures&nbsp;that&nbsp;we&nbsp;operate&nbsp;with&nbsp;transparency&nbsp;and&nbsp;deep&nbsp;respect&nbsp;for&nbsp;the&nbsp;communities&nbsp;we&nbsp;serve.</p><p></p><blockquote>\"True&nbsp;progress&nbsp;is&nbsp;measured&nbsp;not&nbsp;by&nbsp;what&nbsp;we&nbsp;take&nbsp;from&nbsp;the&nbsp;earth,&nbsp;but&nbsp;by&nbsp;what&nbsp;we&nbsp;leave&nbsp;behind.\"</blockquote><p></p><h2><strong>Our&nbsp;Three&nbsp;Pillars&nbsp;of&nbsp;Impact</strong></h2><p></p><p>We&nbsp;focus&nbsp;our&nbsp;efforts&nbsp;on&nbsp;three&nbsp;critical&nbsp;areas&nbsp;to&nbsp;ensure&nbsp;long-term&nbsp;sustainability&nbsp;and&nbsp;ethical&nbsp;growth&nbsp;across&nbsp;all&nbsp;our&nbsp;business&nbsp;sectors.</p><ul><li><strong>Renewable&nbsp;Energy:&nbsp;</strong>Investing&nbsp;in&nbsp;solar&nbsp;and&nbsp;hydroelectric&nbsp;projects.</li><li><strong>Waste&nbsp;Management:</strong>&nbsp;Implementing&nbsp;zero-waste&nbsp;protocols&nbsp;in&nbsp;our&nbsp;offices&nbsp;and&nbsp;sites.</li><li><strong>Community&nbsp;Empowerment:</strong>&nbsp;Providing&nbsp;educational&nbsp;scholarships&nbsp;for&nbsp;local&nbsp;youth.</li></ul>', NULL, '2026-03-13 09:01:40', '2026-03-16 02:53:46', NULL, 1);
INSERT INTO `pages` (`id`, `title`, `slug`, `subtitle`, `heroImage`, `templateType`, `content`, `metaDescription`, `createdAt`, `updatedAt`, `sidebarLinks`, `showDropCap`) VALUES
('bfe3920b-1ea6-4801-8239-b00e4295b981', 'Leading the Global Energy Transition', 'energy-transition', 'Comprehensive Roadmap to Sustainability and Innovation 2030', 'data:image/jpeg;base64,', 'classic', '<h2><strong>The&nbsp;Dawn&nbsp;of&nbsp;a&nbsp;New&nbsp;Era&nbsp;in&nbsp;Resource&nbsp;Management</strong></h2><p class=\"ql-align-justify\">Transformation&nbsp;is&nbsp;not&nbsp;merely&nbsp;a&nbsp;change&nbsp;in&nbsp;direction;&nbsp;it&nbsp;is&nbsp;a&nbsp;profound&nbsp;evolution&nbsp;of&nbsp;spirit&nbsp;and&nbsp;purpose.&nbsp;At&nbsp;DAW&nbsp;Group,&nbsp;we&nbsp;believe&nbsp;that&nbsp;the&nbsp;energy&nbsp;landscape&nbsp;of&nbsp;tomorrow&nbsp;is&nbsp;being&nbsp;built&nbsp;on&nbsp;the&nbsp;pillars&nbsp;of&nbsp;honesty&nbsp;and&nbsp;unwavering&nbsp;persistence&nbsp;today.&nbsp;As&nbsp;we&nbsp;navigate&nbsp;the&nbsp;complexities&nbsp;of&nbsp;the&nbsp;21st&nbsp;century,&nbsp;our&nbsp;commitment&nbsp;remains&nbsp;steadfast:&nbsp;to&nbsp;provide&nbsp;resources&nbsp;that&nbsp;empower&nbsp;humanity&nbsp;while&nbsp;preserving&nbsp;the&nbsp;sanctity&nbsp;of&nbsp;our&nbsp;natural&nbsp;world.</p><blockquote><em>\"Success&nbsp;is&nbsp;born&nbsp;through&nbsp;honesty,&nbsp;persistence,&nbsp;and&nbsp;commitment&nbsp;in&nbsp;the&nbsp;light&nbsp;of&nbsp;constant&nbsp;prayer\"</em>&nbsp;—&nbsp;<strong>The&nbsp;DAW&nbsp;Philosophy</strong></blockquote><p><img src=\"data:image/jpeg;base64,\"></p><p></p><h2 class=\"ql-align-justify\"><strong>Strategic&nbsp;Innovation&nbsp;&amp;&nbsp;Sustainability</strong></h2><p class=\"ql-align-justify\">Our&nbsp;approach&nbsp;to&nbsp;resource&nbsp;development&nbsp;integrates&nbsp;cutting-edge&nbsp;technology&nbsp;with&nbsp;traditional&nbsp;values.&nbsp;We&nbsp;are&nbsp;not&nbsp;just&nbsp;extracting&nbsp;value,&nbsp;we&nbsp;are&nbsp;cultivating&nbsp;a&nbsp;legacy.&nbsp;By&nbsp;investing&nbsp;in&nbsp;renewable&nbsp;infrastructures&nbsp;and&nbsp;optimizing&nbsp;our&nbsp;current&nbsp;energy&nbsp;outputs,&nbsp;we&nbsp;ensure&nbsp;that&nbsp;every&nbsp;kilowatt&nbsp;generated&nbsp;contributes&nbsp;to&nbsp;a&nbsp;larger&nbsp;vision&nbsp;of&nbsp;global&nbsp;stability&nbsp;and&nbsp;environmental&nbsp;harmony.</p><h3 class=\"ql-align-justify\"><strong>Our&nbsp;Core&nbsp;Pillars&nbsp;of&nbsp;Impact</strong></h3><ul><li><strong>Honesty:</strong>&nbsp;Transparent&nbsp;operations&nbsp;and&nbsp;ethical&nbsp;governance&nbsp;in&nbsp;every&nbsp;project.</li><li><strong>Persistence:</strong>&nbsp;Overcoming&nbsp;logistical&nbsp;challenges&nbsp;through&nbsp;engineered&nbsp;excellence.</li><li><strong>Commitment:</strong>&nbsp;A&nbsp;long-term&nbsp;focus&nbsp;on&nbsp;community&nbsp;development&nbsp;and&nbsp;ecological&nbsp;restoration.</li></ul><h2><strong>Future&nbsp;Outlook&nbsp;and&nbsp;Achievements</strong></h2><p class=\"ql-align-justify\">As&nbsp;we&nbsp;look&nbsp;toward&nbsp;the&nbsp;horizon,&nbsp;DAW&nbsp;Group&nbsp;invites&nbsp;you&nbsp;to&nbsp;join&nbsp;us&nbsp;in&nbsp;this&nbsp;journey.&nbsp;Whether&nbsp;through&nbsp;our&nbsp;core&nbsp;resource&nbsp;sectors&nbsp;or&nbsp;our&nbsp;expanding&nbsp;energy&nbsp;portfolio,&nbsp;we&nbsp;are&nbsp;dedicated&nbsp;to&nbsp;driving&nbsp;the&nbsp;transformation&nbsp;that&nbsp;our&nbsp;world&nbsp;deserves.&nbsp;Together,&nbsp;we&nbsp;are&nbsp;building&nbsp;more&nbsp;than&nbsp;just&nbsp;a&nbsp;company;&nbsp;we&nbsp;are&nbsp;building&nbsp;a&nbsp;future.</p>', 'The&nbsp;Dawn&nbsp;of&nbsp;a&nbsp;New&nbsp;Era&nbsp;in&nbsp;Resource&nbsp;ManagementTransformation&nbsp;is&nbsp;not&nbsp;merely&nbsp;a&nbsp;change&nbs...', '2026-03-16 03:49:56', '2026-03-24 09:22:05', '[{\"label\":\"Homepage\",\"url\":\"/\"},{\"label\":\"About Us\",\"url\":\"/about\"}]', 1);

