INSERT INTO `projects` (`id`, `title`, `excerpt`, `content`, `category`, `status`, `author`, `cover_image`, `gallery`, `views`, `createdAt`, `updatedAt`, `seo_title`, `meta_description`) VALUES
('4f4482dd-1df5-11f1-8a02-c03532f000ea', 'CPO Mill and Plantation in West Kalimantan', 'Two CPO mills and 11,000 Ha in West Kalimantan.', '<p>In&nbsp;<strong>West&nbsp;Kalimantan</strong>,&nbsp;DAW&nbsp;Group&nbsp;owns&nbsp;two&nbsp;CPO&nbsp;mills&nbsp;in&nbsp;<strong>Bengkayang&nbsp;</strong>and&nbsp;<strong>Sanggau&nbsp;Region</strong>.&nbsp;Each&nbsp;CPO&nbsp;mill&nbsp;has&nbsp;a&nbsp;capacity&nbsp;of&nbsp;<strong>45&nbsp;tonnes&nbsp;per&nbsp;hour.</strong>&nbsp;</p><p>In&nbsp;<strong>the</strong>&nbsp;<strong>Bengkayang&nbsp;Region</strong>,&nbsp;DAW&nbsp;Group&nbsp;have&nbsp;a&nbsp;palm&nbsp;oil&nbsp;plantation&nbsp;land&nbsp;bank&nbsp;of<strong>&nbsp;11,000&nbsp;Ha.</strong></p><p></p><p>Please&nbsp;check&nbsp;our&nbsp;galleries&nbsp;below&nbsp;for&nbsp;a&nbsp;glimpse&nbsp;of&nbsp;our&nbsp;CPO&nbsp;Mill&nbsp;in&nbsp;West&nbsp;Kalimantan.</p><p></p>', 'Resources', 'Published', 'Jap Calvin', 'cover_image-1773307485898-998356838.jpg', '[\"gallery-1773307485905-887138229.jpg\",\"gallery-1773307485909-748912410.jpg\",\"gallery-1773307485919-506045683.jpg\",\"gallery-1773307485922-749410690.jpg\",\"gallery-1773307485922-562971435.jpeg\"]', 22, '2026-03-12 09:24:45', '2026-03-12 09:25:38', NULL, NULL),
('69f45ba3-1df5-11f1-8a02-c03532f000ea', 'CPO Mill in Jambi', 'Newly acquired 45-tonne CPO mill in Sarolangun, Jambi.', '<p>Our&nbsp;newly&nbsp;acquired&nbsp;CPO&nbsp;mill&nbsp;is&nbsp;located&nbsp;in&nbsp;<strong>Sarolangun</strong>,&nbsp;Jambi.&nbsp;It&nbsp;is&nbsp;a&nbsp;<strong>45&nbsp;tonnes&nbsp;per&nbsp;hour&nbsp;capacity</strong>&nbsp;mill&nbsp;and&nbsp;already&nbsp;in&nbsp;operation&nbsp;since&nbsp;2015.</p><p>Please&nbsp;check&nbsp;our&nbsp;galleries&nbsp;below&nbsp;for&nbsp;a&nbsp;glimpse&nbsp;of&nbsp;our&nbsp;<strong>Palm&nbsp;oil&nbsp;Mill&nbsp;progress</strong>&nbsp;in&nbsp;<strong>Jambi&nbsp;-&nbsp;West&nbsp;Sumatera.</strong></p><p></p>', 'Resources', 'Published', 'Jap Calvin', 'cover_image-1773307530674-706401182.jpg', '[\"gallery-1773307530686-207993754.jpg\",\"gallery-1773307530689-925343087.jpg\",\"gallery-1773307530692-259329630.jpg\",\"gallery-1773307530693-549782054.jpg\",\"gallery-1773307530695-725032504.jpg\"]', 1, '2026-03-12 09:25:30', '2026-03-12 09:25:36', NULL, NULL),
('9990ab1f-1df5-11f1-8a02-c03532f000ea', 'Hydropower - Kualu', '15 MW hydropower project near Lake Toba, North Sumatera.', '<p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Project&nbsp;Kualu</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">&nbsp;is&nbsp;a&nbsp;hydropower&nbsp;(PLTA)&nbsp;project,&nbsp;which&nbsp;has&nbsp;a&nbsp;power&nbsp;potential&nbsp;of&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">15&nbsp;MW</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">.&nbsp;It&nbsp;is&nbsp;located&nbsp;at&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">North&nbsp;Sumatera</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">&nbsp;near&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">the&nbsp;Toba&nbsp;Lake</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">.&nbsp;The&nbsp;name&nbsp;of&nbsp;the&nbsp;river&nbsp;is&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Kualu</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">;&nbsp;the&nbsp;river&nbsp;runs&nbsp;long&nbsp;and&nbsp;is&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">connected</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">&nbsp;to&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">the&nbsp;channels</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">&nbsp;of&nbsp;the&nbsp;Toba&nbsp;Lake.&nbsp;Currently,&nbsp;the&nbsp;project&nbsp;is&nbsp;undergoing&nbsp;a&nbsp;Feasibility&nbsp;Study,&nbsp;which&nbsp;assess&nbsp;Topography&nbsp;study,&nbsp;geology&nbsp;study,&nbsp;and&nbsp;Basic&nbsp;Design&nbsp;of&nbsp;the&nbsp;hydropower&nbsp;plant.</span></p><p><img src=\"http://localhost:5000/uploads/inline_image-1773307601439-267751031.jpg\"></p>', 'Energy', 'Published', 'Jap Calvin', 'cover_image-1773307610567-486901940.jpg', '[\"gallery-1773307610570-764330027.jpg\"]', 5, '2026-03-12 09:26:50', '2026-03-16 09:06:01', NULL, NULL),
('ac7c22e2-1df5-11f1-8a02-c03532f000ea', 'Stockpile - Jambi', 'High-quality PKS stockpile and fuel products in Jambi.', '<p><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">Palm&nbsp;kernel&nbsp;shells&nbsp;</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">(or&nbsp;PKS)&nbsp;a&nbsp;factory&nbsp;that&nbsp;processes&nbsp;oil&nbsp;palm&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">Fresh&nbsp;Fruit&nbsp;Bunches&nbsp;</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">(FFB)&nbsp;into&nbsp;crude&nbsp;palm&nbsp;oil&nbsp;(Crude&nbsp;Palm&nbsp;Oil&nbsp;/&nbsp;CPO)&nbsp;and&nbsp;Palm&nbsp;kernel&nbsp;(Kernel)&nbsp;products.&nbsp;As&nbsp;well&nbsp;as&nbsp;other&nbsp;products&nbsp;such&nbsp;as&nbsp;fiber&nbsp;and&nbsp;shells&nbsp;that&nbsp;can&nbsp;be&nbsp;used&nbsp;as&nbsp;fuel.&nbsp;The&nbsp;palm&nbsp;oil&nbsp;mill&nbsp;(POM)&nbsp;is&nbsp;built&nbsp;based&nbsp;on&nbsp;a&nbsp;certain&nbsp;design&nbsp;according&nbsp;to&nbsp;their&nbsp;wants&nbsp;or&nbsp;needs,&nbsp;accompanied&nbsp;by&nbsp;different&nbsp;technologies&nbsp;and&nbsp;different&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">capacities</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">.</span></p><p></p><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Our&nbsp;Quality&nbsp;PKS</strong></p><ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Calorific&nbsp;value&nbsp;(4k&nbsp;based&nbsp;on&nbsp;ARB)</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Total&nbsp;Moisture&nbsp;15%&nbsp;-&nbsp;20%&nbsp;(depend&nbsp;customer)</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Foreight&nbsp;Matter&nbsp;Max&nbsp;(0,1)</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(51, 51, 51);\">Ash&nbsp;Content&nbsp;(Max&nbsp;3,5&nbsp;%&nbsp;based&nbsp;on&nbsp;ADB)</span></li></ul><p><img src=\"http://localhost:5000/uploads/inlineimage-1773724119917-702878819.jpg\"></p><p></p>', 'Energy', 'Published', 'Jap Calvin', 'cover_image-1773307642310-730089667.jpeg', '[\"gallery-1773307642312-402445926.jpeg\"]', 42, '2026-03-12 09:27:22', '2026-03-17 05:08:49', '', ''),
('f8f4ad92-1df3-11f1-8a02-c03532f000ea', 'Palm Oil Plantation in East Kalimantan', '10,000 Ha palm oil plantation in East Kalimantan.', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">Our&nbsp;first&nbsp;palm&nbsp;oil&nbsp;plantation&nbsp;is&nbsp;located&nbsp;in&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">Kutai&nbsp;Timur&nbsp;Region&nbsp;-&nbsp;East&nbsp;Kalimantan</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">,&nbsp;with&nbsp;total&nbsp;planted&nbsp;area&nbsp;of&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">5,100&nbsp;Ha</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">.&nbsp;The&nbsp;CPO&nbsp;mill,&nbsp;with&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">45&nbsp;tonnes&nbsp;per&nbsp;hour&nbsp;capacity</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">,&nbsp;will&nbsp;commence&nbsp;in&nbsp;mid&nbsp;of&nbsp;2018.&nbsp;Another&nbsp;estate&nbsp;(land&nbsp;bank)&nbsp;is&nbsp;located&nbsp;30&nbsp;Km&nbsp;north&nbsp;of&nbsp;HAL&nbsp;plantation,&nbsp;with&nbsp;total&nbsp;plantable&nbsp;area&nbsp;of&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">5,000&nbsp;Ha.</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">&nbsp;Hence,&nbsp;the&nbsp;total&nbsp;plantable&nbsp;area&nbsp;in&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">East&nbsp;Kalimantan</strong><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">&nbsp;will&nbsp;be&nbsp;</span><strong style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255);\">10,000&nbsp;Ha.&nbsp;</strong></p>', 'Resources', 'Published', 'Jap Calvin', '1773306911586-975036686.jpg', '[\"gallery-1773307381099-381950749.jpg\",\"gallery-1773307381125-605669711.jpg\",\"gallery-1773307381137-320017060.jpg\",\"gallery-1773307381138-174096096.jpg\",\"gallery-1773307381140-622291193.jpg\",\"gallery-1773307381143-115357957.jpg\",\"gallery-1773307381145-771915469.jpg\"]', 41, '2026-03-12 09:15:11', '2026-03-25 10:15:47', '', '');

